package io.github.maaasu.astralRecord.feature.account.service;

import io.github.maaasu.astralRecord.feature.account.model.AccountMode;
import io.github.maaasu.astralRecord.feature.account.model.AccountModel;
import io.github.maaasu.astralRecord.feature.account.repository.AccountRepository;
import io.github.maaasu.astralRecord.infrastructure.logging.LogId;
import io.github.maaasu.astralRecord.infrastructure.logging.Logger;

import java.time.LocalDateTime;
import java.util.List;
import java.util.UUID;

/**
 * アカウント機能のビジネスロジックを担うサービスクラス。
 * アカウントの作成・選択・一覧取得を管理します。
 */
public class AccountService {

    private final AccountRepository accountRepository;

    public AccountService(AccountRepository accountRepository) {
        this.accountRepository = accountRepository;
    }

    /**
     * 指定プレイヤーのアカウント一覧を取得します。
     *
     * @param userId プレイヤー UUID
     * @return アカウントモデルのリスト
     */
    public List<AccountModel> getAccounts(UUID userId) {
        return accountRepository.findByUserId(userId);
    }

    /**
     * アカウント UUID でアカウントを取得します。
     *
     * @param accountUuid アカウント UUID
     * @return アカウントモデル、存在しない場合は null
     */
    public AccountModel getAccount(UUID accountUuid) {
        return accountRepository.findByUuid(accountUuid);
    }

    /**
     * 新規アカウントを作成します。
     * スロット番号の重複チェックを行い、問題なければ登録します。
     *
     * @param userId      プレイヤー UUID
     * @param accountName アカウント名（キャラクター名）
     * @param slotIndex   スロット番号（0始まり）
     * @return 作成したアカウントモデル
     * @throws IllegalArgumentException スロット番号が既に使用中の場合
     */
    public AccountModel createAccount(UUID userId, String accountName, int slotIndex) {
        List<AccountModel> existing = accountRepository.findByUserId(userId);
        boolean slotUsed = existing.stream().anyMatch(a -> a.getSlotIndex() == slotIndex);
        if (slotUsed) {
            throw new IllegalArgumentException("Slot " + slotIndex + " is already in use for user: " + userId);
        }

        LocalDateTime now = LocalDateTime.now();
        AccountModel model = new AccountModel(
            UUID.randomUUID(),
            userId,
            accountName,
            slotIndex,
            existing.isEmpty(),     // 初めてのアカウントであれば自動で is_active = true
            AccountMode.PLAYER,
            now,
            now,
            userId,
            userId,
            false
        );
        AccountModel created = accountRepository.insert(model);
        Logger.log(LogId.I_5100, accountName, slotIndex, userId);
        return created;
    }

    /**
     * 選択中アカウントを切り替えます。
     *
     * @param userId      プレイヤー UUID
     * @param accountUuid 選択するアカウント UUID
     */
    public void switchAccount(UUID userId, UUID accountUuid) {
        accountRepository.switchActiveAccount(userId, accountUuid, userId);
        Logger.log(LogId.I_5101, accountUuid, userId);
    }
}

package io.github.maaasu.astralRecord.feature.account.service;

import io.github.maaasu.astralRecord.feature.account.model.AccountMode;
import io.github.maaasu.astralRecord.feature.account.model.AccountModel;
import io.github.maaasu.astralRecord.feature.account.repository.AccountRepository;
import io.github.maaasu.astralRecord.infrastructure.logging.LogId;
import io.github.maaasu.astralRecord.infrastructure.logging.Logger;

import java.time.LocalDateTime;
import java.util.List;
import java.util.UUID;

/**
 * アカウント機能のビジネスロジックを担うサービスクラス。
 * アカウントの作成・選択・一覧取得を管理します。
 */
public class AccountService {

    private final AccountRepository accountRepository;

    public AccountService(AccountRepository accountRepository) {
        this.accountRepository = accountRepository;
    }

    /**
     * 指定プレイヤーのアカウント一覧を取得します。
     *
     * @param userId プレイヤー UUID
     * @return アカウントモデルのリスト
     */
    public List<AccountModel> getAccounts(UUID userId) {
        return accountRepository.findByUserId(userId);
    }

    /**
     * アカウント UUID でアカウントを取得します。
     *
     * @param accountUuid アカウント UUID
     * @return アカウントモデル、存在しない場合は null
     */
    public AccountModel getAccount(UUID accountUuid) {
        return accountRepository.findByUuid(accountUuid);
    }

    /**
     * 新規アカウントを作成します。
     * スロット番号の重複チェックを行い、問題なければ登録します。
     *
     * @param userId      プレイヤー UUID
     * @param accountName アカウント名（キャラクター名）
     * @param slotIndex   スロット番号（0始まり）
     * @param createdBy   登録者 UUID（新規ユーザー登録フローでは SystemUser、自己作成時はプレイヤー UUID）
     * @return 作成したアカウントモデル
     * @throws IllegalArgumentException スロット番号が既に使用中の場合
     */
    public AccountModel createAccount(UUID userId, String accountName, int slotIndex, UUID createdBy) {
        List<AccountModel> existing = accountRepository.findByUserId(userId);
        boolean slotUsed = existing.stream().anyMatch(a -> a.getSlotIndex() == slotIndex);
        if (slotUsed) {
            throw new IllegalArgumentException("Slot " + slotIndex + " is already in use for user: " + userId);
        }

        LocalDateTime now = LocalDateTime.now();
        AccountModel model = new AccountModel(
            UUID.randomUUID(),
            userId,
            accountName,
            slotIndex,
            existing.isEmpty(),     // 初めてのアカウントであれば自動で is_active = true
            AccountMode.PLAYER,
            now,
            now,
            createdBy,
            createdBy,
            false
        );
        AccountModel created = accountRepository.insert(model);
        Logger.log(LogId.I_5100, accountName, slotIndex, userId);
        return created;
    }

    /**
     * 選択中アカウントを切り替えます。
     *
     * @param userId      プレイヤー UUID
     * @param accountUuid 選択するアカウント UUID
     */
    public void switchAccount(UUID userId, UUID accountUuid) {
        accountRepository.switchActiveAccount(userId, accountUuid, userId);
        Logger.log(LogId.I_5101, accountUuid, userId);
    }
}

package io.github.maaasu.astralRecord.infrastructure.api;

import io.github.maaasu.astralRecord.AstralRecord;
import io.github.maaasu.astralRecord.infrastructure.config.ConfigProperties;
import io.github.maaasu.astralRecord.infrastructure.logging.LogId;
import io.github.maaasu.astralRecord.infrastructure.logging.Logger;

import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;

/**
 * AstralRecord API への疎通確認を行うクラス。
 * プラグイン有効化時に非同期で HTTP リクエストを送信し、接続可否をログに記録します。
 */
public final class ApiHealthChecker {

    private static final String HEALTH_PATH = "/health";

    private ApiHealthChecker() {
        // utility class
    }

    /**
     * 非同期でAPI疎通確認を実行します。
     * PaperAPI の非同期スケジューラを使用するため、メインスレッドをブロックしません。
     */
    public static void checkAsync() {
        AstralRecord plugin = AstralRecord.getInstance();
        plugin.getServer().getAsyncScheduler().runNow(plugin, task -> check());
    }

    /**
     * API疎通確認を同期的に実行します。
     * このメソッドは必ず非同期スレッドから呼び出すこと。
     */
    private static void check() {
        ConfigProperties props = ConfigProperties.getInstance();
        String baseUrl = props.getApiBaseUrl();
        String apiKey = props.getApiAuthApiKey();
        int timeout = props.getApiTimeout();

        String url = baseUrl + HEALTH_PATH;
        Logger.log(LogId.I_1600, url);

        try (HttpClient client = HttpClient.newBuilder()
                .connectTimeout(Duration.ofMillis(timeout))
                .build()) {

            HttpRequest.Builder requestBuilder = HttpRequest.newBuilder()
                    .uri(URI.create(url))
                    .timeout(Duration.ofMillis(timeout))
                    .GET();

            if (apiKey != null && !apiKey.isBlank()) {
                requestBuilder.header("Authorization", "Bearer " + apiKey);
            }

            HttpResponse<Void> response = client.send(
                    requestBuilder.build(),
                    HttpResponse.BodyHandlers.discarding()
            );
            int statusCode = response.statusCode();

            if (statusCode >= 200 && statusCode < 300) {
                Logger.log(LogId.I_1601, statusCode);
            } else {
                Logger.log(LogId.W_1600, statusCode);
            }

        } catch (IOException e) {
            Logger.log(LogId.E_1600, e, url);
        } catch (InterruptedException e) {
            Logger.log(LogId.E_1600, e, url);
            Thread.currentThread().interrupt();
        }
    }
}

package io.github.maaasu.astralRecord.infrastructure.api;

import io.github.maaasu.astralRecord.AstralRecord;
import io.github.maaasu.astralRecord.infrastructure.config.ConfigProperties;
import io.github.maaasu.astralRecord.infrastructure.logging.LogId;
import io.github.maaasu.astralRecord.infrastructure.logging.Logger;

import javax.net.ssl.SSLContext;
import javax.net.ssl.TrustManager;
import javax.net.ssl.X509TrustManager;
import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.security.KeyManagementException;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.security.cert.X509Certificate;
import java.time.Duration;

/**
 * AstralRecord API への疎通確認を行うクラス。
 * プラグイン有効化時に非同期で HTTP リクエストを送信し、接続可否をログに記録します。
 */
public final class ApiHealthChecker {

    private static final String HEALTH_PATH = "/health";

    private ApiHealthChecker() {
        // utility class
    }

    /**
     * 非同期でAPI疎通確認を実行します。
     * PaperAPI の非同期スケジューラを使用するため、メインスレッドをブロックしません。
     */
    public static void checkAsync() {
        AstralRecord plugin = AstralRecord.getInstance();
        plugin.getServer().getAsyncScheduler().runNow(plugin, task -> check());
    }

    /**
     * API疎通確認を同期的に実行します。
     * このメソッドは必ず非同期スレッドから呼び出すこと。
     */
    private static void check() {
        ConfigProperties props = ConfigProperties.getInstance();
        String baseUrl = props.getApiBaseUrl();
        String apiKey = props.getApiAuthApiKey();
        int timeout = props.getApiTimeout();
        boolean sslVerifyEnabled = props.isApiSslVerifyEnabled();

        String url = baseUrl + HEALTH_PATH;
        Logger.log(LogId.I_1600, url);

        try {
            HttpClient.Builder clientBuilder = HttpClient.newBuilder()
                    .connectTimeout(Duration.ofMillis(timeout));

            if (!sslVerifyEnabled) {
                clientBuilder.sslContext(createTrustAllSslContext());
            }

            try (HttpClient client = clientBuilder.build()) {
                HttpRequest.Builder requestBuilder = HttpRequest.newBuilder()
                        .uri(URI.create(url))
                        .timeout(Duration.ofMillis(timeout))
                        .GET();

                if (apiKey != null && !apiKey.isBlank()) {
                    requestBuilder.header("Authorization", "Bearer " + apiKey);
                }

                HttpResponse<Void> response = client.send(
                        requestBuilder.build(),
                        HttpResponse.BodyHandlers.discarding()
                );
                int statusCode = response.statusCode();

                if (statusCode >= 200 && statusCode < 300) {
                    Logger.log(LogId.I_1601, statusCode);
                } else {
                    Logger.log(LogId.W_1600, statusCode);
                }
            }

        } catch (IOException e) {
            Logger.log(LogId.E_1600, e, url);
        } catch (InterruptedException e) {
            Logger.log(LogId.E_1600, e, url);
            Thread.currentThread().interrupt();
        } catch (NoSuchAlgorithmException | KeyManagementException e) {
            Logger.log(LogId.E_1600, e, url);
        }
    }

    /**
     * 全ての SSL 証明書を信頼する SSLContext を生成します。
     * 自己署名証明書や内部CA証明書を使用している環境向けの設定です。
     * {@code api.ssl.verifyEnabled} が {@code false} の場合のみ使用してください。
     */
    private static SSLContext createTrustAllSslContext() throws NoSuchAlgorithmException, KeyManagementException {
        TrustManager[] trustAllCerts = new TrustManager[]{
            new X509TrustManager() {
                @Override
                public X509Certificate[] getAcceptedIssuers() {
                    return new X509Certificate[0];
                }

                @Override
                public void checkClientTrusted(X509Certificate[] certs, String authType) {
                    // すべてのクライアント証明書を信頼
                }

                @Override
                public void checkServerTrusted(X509Certificate[] certs, String authType) {
                    // すべてのサーバー証明書を信頼
                }
            }
        };
        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(null, trustAllCerts, new SecureRandom());
        return sslContext;
    }
}
